#!/usr/bin/env python3
"""Writes tests/gui/exit/OpenDesignsPartsLibraryPins.h from OpenDesignsPartsLibraryProbe's output.

usage: gen_open_designs_parts_library_pins.py PROBE_OUTPUT HEADER COMMIT

PROBE_OUTPUT is the probe's standard output (generate.sh sends OpenRocket's log to standard error): one line
each, its fields separated by tabs (see the probe's class comment). A line out of its place, a dialog without
its view or a non-finite number stops the generator.
"""
import os
import pathlib
import subprocess
import sys

HEADER_TOP = """#pragma once

// GENERATED by tools/openrocket-gui-pins/generate.sh
// (open-designs/gen_open_designs_parts_library_pins.py from the output of
// open-designs/probe/OpenDesignsPartsLibraryProbe.java: OpenRocket's parts library,
// ComponentPresetChooserDialog, as it opens from the configuration dialog of each component of
// the sixteen example designs that takes presets, over the bundled presets, under xvfb with
// SwingPreferences at their defaults and FlatLaf Light; see open_designs_exit_tests.cpp,
// OpenDesignsExitGoldenPartsLibrary); do not edit.

#include <array>
#include <string_view>

namespace QtRocket::Gui::Test
{{

/// The OpenRocket commit the pins come from.
inline constexpr std::string_view kOpenDesignsPartsLibraryPinsCommit = "{commit}";

/// The bundled presets the probe walked (data/components): its .orc files, the presets read from
/// them and the presets the database kept.
inline constexpr int kOpenDesignsPartsLibraryFiles       = {files};
inline constexpr int kOpenDesignsPartsLibraryPresetsRead = {read};
inline constexpr int kOpenDesignsPartsLibraryPresetsKept = {kept};

/// A diameter box of the parts library: whether the dialog shows it (OpenRocket makes some it
/// never adds: no neighbour, or a type without the column), its text and tooltip, whether it is
/// ticked when the dialog opens, and its filter (ComponentPresetRowFilter's dvalue and epsilon:
/// the neighbour's diameter in m and the tolerance; 0 when the box is not shown).
struct PartsLibraryBoxPin
{{
    bool             shown;
    std::string_view text;
    std::string_view toolTip;
    bool             checked;
    double           diameter;
    double           tolerance;
}};

/// The parts library of one component of an example design, as OpenRocket's "Parts Library"
/// button of the component's configuration dialog opens it (RocketComponentConfig.selectPreset()),
/// with the default filters:
/// - the design (the name of its tests in OpenDesignsExitGolden) and the component: its place in
///   the rocket's iteration order (the rocket 0, every component before its children), its name,
///   getComponentName(), getPresetType() and what the dialog's preset combo box shows when closed
///   (the component's preset by its part number; empty for "Custom");
/// - the other default filters: the "Show Legacy Database" box (its text and whether it is
///   ticked) and the text of the "Filter by text" field;
/// - the "Match fore diameter" and "Match aft diameter" boxes (for a flipped nose cone the aft box
///   has the fore box's text); for a flipped nose cone whose previous component's radii differ,
///   @c aft holds QtRocket's filter, that component's aft diameter (bug 16 of the plan's section
///   10.3, fixed), and @c openRocketAftDiameter OpenRocket's, its fore diameter, and the views
///   were taken with the fixed filter; otherwise the two diameters are equal;
/// - the "Always open this dialog when creating a new <name>" box;
/// - the table as the dialog opens (@c openView, "rows <n> md5 <hex>": its rows and the MD5 of
///   their presets' keys in view order, presetDigestOfView()) and its first @c rowCount rows,
///   kOpenDesignsPartsLibraryRows[firstRow] onwards (the texts of their shown cells in view
///   order, but the favourite's check box, separated by " | "); with every shown diameter box
///   unticked, @c unmatchedView (empty when the dialog shows no ticked box).
struct PartsLibraryPin
{{
    std::string_view   design;
    int                component;
    std::string_view   name;
    std::string_view   componentName;
    std::string_view   presetType;
    std::string_view   preset;
    std::string_view   legacyText;
    bool               legacyChecked;
    std::string_view   filterText;
    PartsLibraryBoxPin fore;
    PartsLibraryBoxPin aft;
    double             openRocketAftDiameter;
    std::string_view   alwaysOpenText;
    bool               alwaysOpenChecked;
    std::string_view   openView;
    int                firstRow;
    int                rowCount;
    std::string_view   unmatchedView;
}};

// clang-format off
// NOLINTBEGIN(modernize-use-designated-initializers): tables printed by the Java probe
// NOLINTBEGIN(modernize-raw-string-literal): the texts escaped alike, quotes and non-ASCII
"""

HEADER_BOTTOM = """// NOLINTEND(modernize-raw-string-literal)
// NOLINTEND(modernize-use-designated-initializers)
// clang-format on

}  // namespace QtRocket::Gui::Test
"""


def fail(message):
    raise SystemExit("gen_open_designs_parts_library_pins.py: " + message)


def cpp_string(text):
    """A C++ string literal of @p text: printable ASCII as it is, a character of the BMP as a \\u escape
    (no split literal: the tables are braced lists, bugprone-suspicious-missing-comma)."""
    out = []
    for ch in text:
        code = ord(ch)
        if ch in "\\\"":
            out.append("\\" + ch)
        elif 0x20 <= code < 0x7F:
            out.append(ch)
        elif 0xA0 <= code <= 0xFFFF and not 0xD800 <= code <= 0xDFFF:
            out.append("\\u%04X" % code)
        else:
            fail("a character that cannot be written: %r" % text)
    return '"' + "".join(out) + '"'


def hex_double(text):
    value = float.fromhex(text)
    if value != value or value in (float("inf"), float("-inf")):
        fail("a non-finite number: " + text)
    return text


def boolean(text):
    if text not in ("true", "false"):
        fail("not a boolean: " + text)
    return text


def expect_fields(fields, count, line):
    if len(fields) != count:
        fail("%d fields expected: %r" % (count, line))


def parse(lines):
    database = None
    designs = []
    components = []
    current = None
    for line in lines:
        line = line.rstrip("\n")
        fields = line.split("\t")
        tag = fields[0]
        if tag == "DATABASE":
            expect_fields(fields, 4, line)
            database = [int(f) for f in fields[1:]]
        elif tag == "D":
            expect_fields(fields, 2, line)
            designs.append(fields[1])
            current = None
        elif tag == "C":
            expect_fields(fields, 6, line)
            if not designs:
                fail("a component before a design: " + line)
            current = {"design": designs[-1], "index": int(fields[1]), "name": fields[2], "componentName": fields[3],
                       "type": fields[4], "preset": fields[5], "boxes": {}, "filters": {}, "fixed": None,
                       "rows": [], "views": {}}
            components.append(current)
        elif current is None:
            fail("a line before a component: " + line)
        elif tag == "L":
            expect_fields(fields, 4, line)
            if "legacy" in current:
                fail("a second L line: " + line)
            current["legacy"] = (fields[1], boolean(fields[2]), fields[3])
        elif tag == "B":
            if fields[2:] == ["none"]:
                current["boxes"][fields[1]] = None
            else:
                expect_fields(fields, 5, line)
                current["boxes"][fields[1]] = (fields[2], "" if fields[3] == "null" else fields[3],
                                               boolean(fields[4]))
        elif tag == "F":
            if fields[2:] == ["none"]:
                current["filters"][fields[1]] = None
            else:
                expect_fields(fields, 4, line)
                current["filters"][fields[1]] = (hex_double(fields[2]), hex_double(fields[3]))
        elif tag == "X":
            expect_fields(fields, 5, line)
            current["fixed"] = (hex_double(fields[2]), hex_double(fields[3]), hex_double(fields[4]))
        elif tag == "A":
            expect_fields(fields, 3, line)
            current["always"] = (fields[1], boolean(fields[2]))
        elif tag == "V":
            expect_fields(fields, 3, line)
            if fields[1] not in ("open", "unmatched") or fields[1] in current["views"]:
                fail("an unexpected view: " + line)
            current["views"][fields[1]] = fields[2]
        elif tag == "R":
            if int(fields[1]) != len(current["rows"]) or "unmatched" in current["views"]:
                fail("a row out of its place: " + line)
            current["rows"].append(" | ".join(fields[2:]))
        else:
            fail("an unexpected line: " + line)
    if database is None:
        fail("no DATABASE line")
    for c in components:
        if set(c["boxes"]) != {"fore", "aft"} or set(c["filters"]) != {"fore", "aft"} or "always" not in c \
                or "legacy" not in c or "open" not in c["views"]:
            fail("a dialog without all its lines: %s %d" % (c["design"], c["index"]))
        for side in ("fore", "aft"):
            if (c["boxes"][side] is None) != (c["filters"][side] is None):
                fail("a box without its filter or a filter without its box: %s %d" % (c["design"], c["index"]))
        ticked = any(box is not None and box[2] == "true" for box in c["boxes"].values())
        if ticked != ("unmatched" in c["views"]):
            fail("the unmatched view does not follow the ticked boxes: %s %d" % (c["design"], c["index"]))
    return database, designs, components


def box_pin(box, diameter_filter):
    if box is None:
        return '{false, "", "", false, 0.0, 0.0}'
    text, tip, checked = box
    diameter, tolerance = diameter_filter
    return "{true, %s, %s, %s, %s, %s}" % (cpp_string(text), cpp_string(tip), checked, diameter, tolerance)


def table(out, element, name, rows):
    out.append("inline constexpr std::array<%s, %d> %s{{" % (element, len(rows), name))
    out.extend(rows)
    out.append("}};")


def main():
    probe, header, commit = sys.argv[1:4]
    with open(probe, encoding="utf-8") as f:
        (files, read, kept), designs, components = parse(f.readlines())
    out = [HEADER_TOP.format(commit=commit, files=files, read=read, kept=kept)]
    rows = []
    blocks = {}
    pins = []
    for c in components:
        # A dialog whose first rows are those of an earlier one shares that one's rows.
        block = tuple(c["rows"])
        if block not in blocks:
            blocks[block] = len(rows)
            rows.extend("    %s," % cpp_string(row) for row in block)
        first = blocks[block]
        aft_filter = c["filters"]["aft"]
        openrocket_aft = aft_filter[0] if aft_filter is not None else "0.0"
        if c["fixed"] is not None:
            openrocket_aft, fixed, fixed_tolerance = c["fixed"]
            if aft_filter != (fixed, fixed_tolerance):
                fail("a fixed filter the F line does not hold: %s %d" % (c["design"], c["index"]))
        always_text, always_checked = c["always"]
        legacy_text, legacy_checked, filter_text = c["legacy"]
        fields = (cpp_string(c["design"]), c["index"], cpp_string(c["name"]), cpp_string(c["componentName"]),
                  cpp_string(c["type"]), cpp_string(c["preset"]), cpp_string(legacy_text), legacy_checked,
                  cpp_string(filter_text), box_pin(c["boxes"]["fore"], c["filters"]["fore"]),
                  box_pin(c["boxes"]["aft"], c["filters"]["aft"]), openrocket_aft, cpp_string(always_text),
                  always_checked, cpp_string(c["views"]["open"]), first, len(c["rows"]),
                  cpp_string(c["views"].get("unmatched", "")))
        pins.append("    {%s, %d, %s, %s, %s, %s,\n     %s, %s, %s,\n     %s,\n     %s,\n"
                    "     %s, %s, %s, %s, %d, %d, %s}," % fields)
    out.append("/// The example designs, in the probe's order (OpenDesignsExitGolden's).")
    table(out, "std::string_view", "kOpenDesignsPartsLibraryDesigns", ["    %s," % cpp_string(d) for d in designs])
    out.append("")
    out.append("/// The first rows of the dialogs, dialog after dialog (a dialog whose first rows are those of an earlier")
    out.append("/// one shares them).")
    table(out, "std::string_view", "kOpenDesignsPartsLibraryRows", rows)
    out.append("")
    out.append("/// The parts libraries, design after design, each design's components in their order.")
    table(out, "PartsLibraryPin", "kOpenDesignsPartsLibraries", pins)
    out.append("")
    out.append(HEADER_BOTTOM)
    with open(header, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(out))
    # The repository's style (its .clang-format, wherever the header is written: generate.sh --check
    # writes it into a temporary directory), so that a run reproduces the committed header byte for byte.
    style_file = pathlib.Path(__file__).resolve().parents[3] / ".clang-format"
    clang_format = os.environ.get("CLANG_FORMAT", "clang-format")
    subprocess.run([clang_format, "-i", f"--style=file:{style_file}", header], check=True)


if __name__ == "__main__":
    main()
